input.old_string:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100dvh;
  background: radial-gradient(ellipse at top, #2a1538 0%, var(--bg) 55%);
}

#root {
  min-height: 100dvh;
}

input.new_string:
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  width: 100%;
  height: 100%;
  min-height: 100vh;
  min-height: 100dvh;
}

html,
body {
  margin: 0;
  padding: 0;
  overflow-x: hidden;
}

body {
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  height: 100%;
  background: radial-gradient(ellipse at top, #2a1538 0%, var(--bg) 55%);
}

#root {
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  height: 100%;
  display: flex;
  flex-direction: column;
}

input.old_string:
.app-shell {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  max-width: 480px;
  margin: 0 auto;
}

.app-header {
  padding: 1rem 1.25rem 0.5rem;
  text-align: center;
}

input.new_string:
.app-shell {
  width: 100%;
  flex: 1 1 auto;
  min-height: 100vh;
  min-height: 100dvh;
  height: 100%;
  max-height: 100dvh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.app-header {
  flex-shrink: 0;
  width: 100%;
  max-width: 30rem;
  margin-inline: auto;
  padding: 1rem 1.25rem 0.5rem;
  text-align: center;
}

input.old_string:
.app-main {
  flex: 1;
  padding: 0 1rem calc(var(--nav-h) + var(--safe-bottom) + 1rem);
  overflow-y: auto;
}

.bottom-nav {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 480px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2px;
  padding: 0.35rem 0.5rem calc(0.35rem + var(--safe-bottom));
  background: rgba(13, 8, 18, 0.92);
  backdrop-filter: blur(12px);
  border-top: 1px solid rgba(232, 121, 249, 0.15);
  z-index: 100;
}

@media (min-width: 400px) {
  .bottom-nav {
    grid-template-columns: repeat(6, 1fr);
  }
}

input.new_string:
.app-main {
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  max-width: 30rem;
  margin-inline: auto;
  padding: 0 1rem calc(var(--nav-h) + var(--safe-bottom) + 1rem);
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

.bottom-nav {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  width: 100%;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2px;
  padding: 0.35rem 0.5rem calc(0.35rem + var(--safe-bottom));
  padding-left: max(0.5rem, env(safe-area-inset-left, 0px));
  padding-right: max(0.5rem, env(safe-area-inset-right, 0px));
  background: rgba(13, 8, 18, 0.92);
  backdrop-filter: blur(12px);
  border-top: 1px solid rgba(232, 121, 249, 0.15);
  z-index: 100;
}

@media (min-width: 400px) {
  .bottom-nav {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }
}

.bottom-nav:has(.nav-link:nth-child(7)) {
  grid-template-columns: repeat(auto-fit, minmax(0, 1fr));
}

.page {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  width: 100%;
  min-width: 0;
}

#root > .page {
  flex: 1 1 auto;
  min-height: 100vh;
  min-height: 100dvh;
  max-width: 30rem;
  margin-inline: auto;
  padding: 1rem;
  padding-bottom: calc(1rem + var(--safe-bottom));
  overflow-x: hidden;
  overflow-y: auto;
}

input.old_string:
.login-page {
  min-height: 100dvh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  max-width: 480px;
  margin: 0 auto;
}

.login-card {
  width: 100%;
  text-align: center;
}

input.new_string:
.login-page {
  flex: 1 1 auto;
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  padding-left: max(1.5rem, env(safe-area-inset-left, 0px));
  padding-right: max(1.5rem, env(safe-area-inset-right, 0px));
  overflow-x: hidden;
}

.login-card {
  width: 100%;
  max-width: 30rem;
  text-align: center;
}

input.old_string:
.auth-loading {
  min-height: 100dvh;
  display: grid;
  place-items: center;
  max-width: 480px;
  margin: 0 auto;
}

input.new_string:
.auth-loading {
  flex: 1 1 auto;
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 1.5rem;
}

.nav-icon {
  font-size: 1.1rem;
}

.nav-label {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: center;
}
